// Character weapon combat bridge. Weapon definitions are supplied by the server;
// the UI only chooses an equipped hand and enters physical dice totals.
function sourceWeaponOptions(source){
  if(!source)return[];
  if(source.source_type==='weapon_attack'&&source.weapon_slot&&source.weapon)return[{slot:source.weapon_slot,weapon_id:source.weapon.weapon_id,name:source.weapon.weapon_name,weapon:source.weapon}];
  return Array.isArray(source.weapon_options)?source.weapon_options:[];
}
