renderActive=function(participant){weaponAwarePreviousRenderActive(participant);if(!participant)return;const source=$('#combat-source');renderCombatWeaponField(null);const setSource=()=>{const index=source.value===''?null:+source.value,c=index===null?null:participant.content[index];state.activeSource=c;state.activeWeaponSlot=c?.weapon_slot||null;renderCombatWeaponField(c);$('#combat-attack-formula').textContent=participant.participant_type==='character'?(c?.attack_roll||'Keine Trefferformel hinterlegt'):'Für diesen Aktortyp ist keine Trefferprüfung erforderlich';$('#combat-formula').textContent=c?.calculation||'Keine Schadensformel hinterlegt';updateCombatWeaponFormula(c);$('#hit-roll').value='';$('#target-roll').value='';renderDiceInputs();updateMagicAttributeField();updateResourceCostHint()};source.onchange=setSource};
