renderDiceInputs=function(){weaponAwarePreviousRenderDiceInputs();const source=state.activeSource,attack=$('#combat-attack-formula')?.textContent||'',isCharacter=state.activeParticipant?.participant_type==='character',needsAttack=isCharacter&&/w20|waffenangriff|normaler angriff|ausweichwurf|angriffswurf/i.test(attack);$('#attack-formula-field')?.classList.toggle('hidden',!needsAttack);$('#hit-roll-fields')?.classList.toggle('hidden',!needsAttack);$('#target-roll-field')?.classList.add('hidden');const root=$('#dice-inputs');if(!root)return;root.innerHTML='';if(!source)return;const chosen=selectedSourceWeapon(source),weaponDamage=(source.source_type==='weapon_attack'||source.uses_normal_weapon_damage===true||source.weapon_usage_type==='normal_weapon_damage')&&chosen?.weapon?.damage_formula;const formula=$('#combat-formula')?.textContent||'',notations=[...new Set((formula.match(/\b(?:\d*)W\d+\b/gi)||[]).map(n=>n.toUpperCase().replace(/^W/,'1W')))];if(weaponDamage){root.insertAdjacentHTML('beforeend','<label id="weapon-damage-roll-field">Waffenschadenswürfel<input id="weapon-damage-roll" type="number" min="0" step="1" inputmode="numeric"></label>');const weaponNotations=[...new Set((String(weaponDamage).match(/\b(?:\d*)W\d+\b/gi)||[]).map(n=>n.toUpperCase().replace(/^W/,'1W')))];if(notations.some(n=>!weaponNotations.includes(n)))root.insertAdjacentHTML('beforeend','<label id="effect-roll-field">Effektwürfel<input id="effect-roll" type="number" min="0" step="1" inputmode="numeric"></label>');}else if(notations.length||/schadenswürfel|effektwürfel|heilungswürfel/i.test(formula)){root.insertAdjacentHTML('beforeend','<label id="effect-roll-field">Schadens-/Effektwürfel<input id="effect-roll" type="number" min="0" step="1" inputmode="numeric"></label>');}if(needsAttack)$('#hit-roll-field').firstChild.textContent='Trefferwürfel'};
