  const setView=view=>{detail.dataset.mobileView=view;tabs.forEach(tab=>{const active=tab.dataset.combatView===view;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',active?'true':'false')})};
  tabs.forEach(tab=>tab.addEventListener('click',()=>setView(tab.dataset.combatView)));
  setView(detail.dataset.mobileView||'combat');
